import java.util.*; import java.util.concurrent.*; public class ServerStatusAfterSplit { private final Set<String> users = new HashSet<>(); private final Set<String> queries = new HashSet<>(); public void addUser(String u) { synchronized (users) { users.add(u); } } public void addQuery(String q) { synchronized (queries) { queries.add(q); } } public void removeUser(String u) { synchronized (users) { users.remove(u); } } public void removeQuery(String q) { synchronized (queries) { queries.remove(q); } } public static void main(String[] args) throws Exception { ServerStatusAfterSplit status = new ServerStatusAfterSplit(); ExecutorService es = Executors.newFixedThreadPool(2); es.execute(() -> { status.addUser(String.valueOf(1)); }); es.execute(() -> { status.addQuery(String.valueOf(2)); }); es.shutdown(); es.awaitTermination(1, TimeUnit.SECONDS); } }
